import{_ as e,o as a,c as s,ag as d}from"./chunks/framework.DaCm-iTo.js";const k=JSON.parse('{"title":"物品装配系统","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/assembly.md","filePath":"modules/corelib/assembly.md","lastUpdated":null}'),i={name:"modules/corelib/assembly.md"};function o(r,t,n,l,p,c){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="物品装配系统" tabindex="-1">物品装配系统 <a class="header-anchor" href="#物品装配系统" aria-label="Permalink to &quot;物品装配系统&quot;">​</a></h1><p>装配系统用于把多个模块写入的物品状态合并成最终显示。它是装备成长线的核心基础设施之一。</p><h2 id="为什么需要装配系统" tabindex="-1">为什么需要装配系统 <a class="header-anchor" href="#为什么需要装配系统" aria-label="Permalink to &quot;为什么需要装配系统&quot;">​</a></h2><p>在 RPG 服务器中，同一件装备可能同时拥有：</p><ul><li>EmakiItem 写入的基础名称、基础 Lore、套装、技能。</li><li>EmakiForge 写入的品质、锻造材料、额外属性。</li><li>EmakiStrengthen 写入的星级、强化加成、失败标记。</li><li>EmakiGem 写入的插槽、宝石、宝石等级。</li><li>EmakiAttribute 写入或读取的属性 payload。</li></ul><p>如果每个模块都直接改最终 Lore，就会产生覆盖、重复、顺序混乱和残留。装配系统的做法是：各模块写入自己的结构化 layer，CoreLib 再统一渲染最终展示。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>namespace layer</td><td>每个模块在物品上的数据层，包含该模块写入的所有状态。</td></tr><tr><td>order</td><td>层的排序权重，决定最终 Lore 中各模块展示的先后顺序。</td></tr><tr><td>snapshot</td><td>层数据的快照，用于编解码和持久化。</td></tr><tr><td>contribution</td><td>层对最终展示的贡献，包括 Lore section、名称修饰和属性统计。</td></tr><tr><td>renderer</td><td>渲染器，负责把所有 contribution 合并成最终 ItemMeta。</td></tr></tbody></table><h2 id="namespace-layer" tabindex="-1">namespace layer <a class="header-anchor" href="#namespace-layer" aria-label="Permalink to &quot;namespace layer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Namespace</th><th>Order</th><th>说明</th></tr></thead><tbody><tr><td><code>forge</code></td><td><code>100</code></td><td>锻造层。包含品质、材料贡献、锻造配方信息。</td></tr><tr><td><code>strengthen</code></td><td><code>200</code></td><td>强化层。包含星级、锻印、保护状态、强化属性。</td></tr><tr><td><code>gem</code></td><td><code>300</code></td><td>宝石层。包含插槽、宝石、等级、宝石属性。</td></tr><tr><td><code>cooking</code></td><td><code>10000</code></td><td>烹饪展示层或特殊展示。</td></tr></tbody></table><p><code>order</code> 越小越靠前。这样可以控制最终 Lore 中各模块展示顺序。</p><h2 id="装配流程" tabindex="-1">装配流程 <a class="header-anchor" href="#装配流程" aria-label="Permalink to &quot;装配流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 业务模块完成操作（如强化成功、宝石镶嵌）</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. 模块把真实状态写入 PDC（layer snapshot）</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. 模块通过 ItemOperationLedger 执行 name_actions/lore_actions</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>4. Ledger 记录操作到 PDC（emaki:item.operations），支持后续精确回退</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>5. 返回更新后的 ItemStack</span></span></code></pre></div><p>当需要回退操作时（如宝石提取、强化降级）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 模块调用 Ledger.revert(operationId) 或 Ledger.revertAll(sourceNamespace)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. Reverter 根据账本记录精确撤销对应的名称/Lore 修改</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. 不影响其他模块的操作结果</span></span></code></pre></div><h2 id="关键服务" tabindex="-1">关键服务 <a class="header-anchor" href="#关键服务" aria-label="Permalink to &quot;关键服务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>说明</th></tr></thead><tbody><tr><td><code>EmakiItemAssemblyService</code></td><td>物品装配入口，负责接收重建请求并协调各 layer。</td></tr><tr><td><code>ItemOperationLedger</code></td><td>统一 Name/Lore 操作账本，支持精确回退。</td></tr><tr><td><code>ItemOperationExecutor</code></td><td>执行 name_actions/lore_actions 并记录变更。</td></tr><tr><td><code>ItemOperationReverter</code></td><td>根据账本记录精确回退操作。</td></tr><tr><td><code>EmakiNamespaceRegistry</code></td><td>namespace 注册和顺序管理，维护所有已注册 layer 的 order。</td></tr><tr><td><code>EmakiItemLayerCodecRegistry</code></td><td>layer 数据编码、解码和兼容，处理版本迁移。</td></tr></tbody></table><h2 id="lore-操作账本-itemoperationledger" tabindex="-1">Lore 操作账本（ItemOperationLedger） <a class="header-anchor" href="#lore-操作账本-itemoperationledger" aria-label="Permalink to &quot;Lore 操作账本（ItemOperationLedger）&quot;">​</a></h2><p>每次模块对物品执行 <code>name_actions</code> 或 <code>lore_actions</code> 时，Ledger 会生成一条带 <code>operationId</code> 的记录存入物品 PDC（<code>emaki:item.operations</code>）。</p><p>每条记录包含：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>operationId</code></td><td>操作唯一标识。</td></tr><tr><td><code>sourceNamespace</code></td><td>来源模块标识（如 <code>gem</code>、<code>strengthen</code>、<code>forge</code>）。</td></tr><tr><td><code>timestamp</code></td><td>操作时间戳。</td></tr><tr><td><code>nameRecords</code></td><td>名称修改记录（用于回退）。</td></tr><tr><td><code>loreRecords</code></td><td>Lore 修改记录（用于回退）。</td></tr></tbody></table><p>核心 API：</p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>apply(itemStack, operationId, sourceNamespace, nameActions, loreActions, variables)</code></td><td>执行操作并记录到 PDC。</td></tr><tr><td><code>revert(itemStack, operationId)</code></td><td>精确撤销指定操作。</td></tr><tr><td><code>revertAll(itemStack, sourceNamespace)</code></td><td>清空某命名空间的所有操作。</td></tr></tbody></table><h2 id="名称修饰-name-contribution" tabindex="-1">名称修饰（Name Contribution） <a class="header-anchor" href="#名称修饰-name-contribution" aria-label="Permalink to &quot;名称修饰（Name Contribution）&quot;">​</a></h2><p>除了 Lore，layer 还可以修饰物品名称。例如：</p><ul><li>强化层在名称前添加 <code>+10</code>。</li><li>锻造层在名称后添加品质标签 <code>[史诗]</code>。</li><li>宝石层不修改名称。</li></ul><p>名称修饰支持位置控制：</p><table tabindex="0"><thead><tr><th>位置</th><th>说明</th></tr></thead><tbody><tr><td><code>PREFIX</code></td><td>添加到名称前面。</td></tr><tr><td><code>POSTFIX</code></td><td>添加到名称后面。</td></tr></tbody></table><p>多个 layer 的名称修饰按 order 排序拼接。</p><blockquote><p>注意：位置枚举值为 <code>PREFIX</code> 和 <code>POSTFIX</code>，不是 <code>SUFFIX</code>。</p></blockquote><h2 id="配置者能做什么" tabindex="-1">配置者能做什么 <a class="header-anchor" href="#配置者能做什么" aria-label="Permalink to &quot;配置者能做什么&quot;">​</a></h2><p>配置者通常不直接操作装配服务，但会影响装配结果：</p><h3 id="调整-lore-模板" tabindex="-1">调整 Lore 模板 <a class="header-anchor" href="#调整-lore-模板" aria-label="Permalink to &quot;调整 Lore 模板&quot;">​</a></h3><p>各模块通常在自己的配置中提供 Lore 模板：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># EmakiStrengthen 配置示例</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;强化等级：&lt;yellow&gt;+%star%&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;强化加成：&lt;green&gt;+%bonus_attack% 攻击&#39;</span></span></code></pre></div><h3 id="调整属性展示格式" tabindex="-1">调整属性展示格式 <a class="header-anchor" href="#调整属性展示格式" aria-label="Permalink to &quot;调整属性展示格式&quot;">​</a></h3><p>在 EmakiAttribute 的 <code>lore_formats/</code> 中定义属性如何显示：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># lore_formats/default_flat.yml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;%display_name%：&lt;white&gt;+%value%&#39;</span></span></code></pre></div><h3 id="控制展示开关" tabindex="-1">控制展示开关 <a class="header-anchor" href="#控制展示开关" aria-label="Permalink to &quot;控制展示开关&quot;">​</a></h3><p>部分模块允许配置是否显示某些状态：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  show_quality</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  show_material_info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  show_star_level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  show_gem_slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h3 id="使用模块命令刷新装备" tabindex="-1">使用模块命令刷新装备 <a class="header-anchor" href="#使用模块命令刷新装备" aria-label="Permalink to &quot;使用模块命令刷新装备&quot;">​</a></h3><p>当配置变更后，已有装备的展示不会自动更新。需要使用模块提供的刷新命令：</p><ul><li>手动刷新单件装备。</li><li>批量刷新在线玩家装备。</li><li>玩家登录时自动刷新（如果模块支持）。</li></ul><h2 id="设计装备展示的建议" tabindex="-1">设计装备展示的建议 <a class="header-anchor" href="#设计装备展示的建议" aria-label="Permalink to &quot;设计装备展示的建议&quot;">​</a></h2><ul><li><strong>把&quot;真实数值&quot;交给 PDC / 属性 payload，不要只写 Lore</strong>。Lore 是展示层，PDC 是数据层。</li><li><strong>Lore 中只展示玩家需要看到的信息</strong>。不要把内部调试数据写进 Lore。</li><li><strong>每个模块的 Lore 区块保持边界清晰</strong>。例如锻造区、强化区、宝石区各自独立，不要交叉。</li><li><strong>不要让多个模块写同一行含义相同的属性</strong>。例如攻击力只在一个地方展示，避免玩家误解。</li><li><strong>对旧装备升级时，先在测试服抽样刷新</strong>。确认新模板不会破坏旧数据的展示。</li><li><strong>名称修饰保持简洁</strong>。<code>+10 烈焰剑 [史诗]</code> 比 <code>[+10][史诗][锻造][宝石x3] 烈焰剑</code> 更易读。</li></ul><h2 id="装配触发时机" tabindex="-1">装配触发时机 <a class="header-anchor" href="#装配触发时机" aria-label="Permalink to &quot;装配触发时机&quot;">​</a></h2><p>以下操作会触发物品重建：</p><table tabindex="0"><thead><tr><th>操作</th><th>触发模块</th></tr></thead><tbody><tr><td>强化成功/失败</td><td>EmakiStrengthen</td></tr><tr><td>锻造完成</td><td>EmakiForge</td></tr><tr><td>宝石镶嵌/提取/升级</td><td>EmakiGem</td></tr><tr><td>物品自动更新</td><td>EmakiItem</td></tr><tr><td>手动刷新命令</td><td>各模块</td></tr><tr><td>属性同步</td><td>EmakiAttribute</td></tr></tbody></table><h2 id="lore-操作的锚点行为" tabindex="-1">Lore 操作的锚点行为 <a class="header-anchor" href="#lore-操作的锚点行为" aria-label="Permalink to &quot;Lore 操作的锚点行为&quot;">​</a></h2><p>当 <code>lore_actions</code> 中使用 <code>insert_below</code> 或 <code>insert_above</code> 操作时，<code>anchor</code> 为空和 <code>anchor</code> 未匹配到任何行的结果并不相同：</p><table tabindex="0"><thead><tr><th>操作</th><th><code>anchor</code> 为空</th><th><code>anchor</code> 未匹配到任何行</th></tr></thead><tbody><tr><td><code>insert_below</code></td><td>插入到 Lore 末尾。</td><td>插入到 Lore 末尾。</td></tr><tr><td><code>insert_above</code></td><td>插入到 Lore 开头。</td><td>插入到 Lore 末尾。</td></tr></tbody></table><p>anchor 采用<strong>包含</strong>匹配，命中第一行即停止；<code>insert_below</code> 插到该行之后，<code>insert_above</code> 插到该行之前。</p><h2 id="namespace-id-规范化" tabindex="-1">Namespace ID 规范化 <a class="header-anchor" href="#namespace-id-规范化" aria-label="Permalink to &quot;Namespace ID 规范化&quot;">​</a></h2><p>注册 namespace 时，ID 会被自动规范化：</p><ul><li>去除首尾空格。</li><li>转为小写。</li><li>空格替换为下划线。</li><li>空字符串变为 <code>unknown</code>。</li></ul>`,56)])])}const b=e(i,[["render",o]]);export{k as __pageData,b as default};
